TW
private readonly List<string> exDesign = new List<string>();
public TwoWheeler()
{

}
public TwoWheeler(string model,int yearMake,int cc,VehicleType vehicleType,double mileage,string startingMethod):base(model,yearMake,cc,vehicleType)
{
    this.Mileage = mileage;
    this.StartingMethod = startingMethod;
}
public double Mileage { get; set; }
public string StartingMethod { get; set; }

public void AddExteriorDesign(params string[] designs)
{
    this.exDesign.AddRange(designs);
}

public override string Details()
{
    return $"{Model}, {CC}cc {YearMake}\n{Mileage}KMPL {StartingMethod}";
}

public string GetExteriorDesign()
{
    return string.Join(", ", this.exDesign);
}
