Bike
public MotorCycle() { }
public MotorCycle(string model, int yearMake, int cc, VehicleType vehicleType,double mileage,string startingMethod, string frontBreak, string rearBreak):base(model, yearMake, cc, vehicleType,mileage,startingMethod)
{
    this.FrontBreak = frontBreak;
    this.RearBreak = rearBreak;
}
public string FrontBreak { get; set; }
public string RearBreak { get; set; }
public override string Details()
{
    return $"{base.Details()}\nFront Break {FrontBreak}, Rear Break {RearBreak}";
}
