public Car() //Default Constructor
{ 

}
public Car(string model, int yearMake, int cc, VehicleType vehicleType, int noOfSeats,int noOfDoors):base(model, yearMake, cc, vehicleType,noOfSeats)
{
    this.NumberOfDoors = noOfDoors;
}
public int NumberOfDoors { get; set; }
public override string Details()
{
    return $"{base.Details()}, {NumberOfDoors} doors";
}
